import 'dart:math' as math;

class EngineeringValue {
  const EngineeringValue(this.value, this.unit, {this.digits = 2});
  final double value;
  final String unit;
  final int digits;
  String get display => '${value.toStringAsFixed(digits)}${unit.isEmpty ? '' : ' $unit'}';
  Map<String, Object?> toJson() => {'value': value, 'unit': unit, 'digits': digits};
}

class AdvancedEngineeringResult {
  const AdvancedEngineeringResult({required this.key, required this.title, required this.status, required this.inputs, required this.metrics, required this.formula, required this.assumptions, this.warnings = const []});
  final String key, title, status, formula;
  final Map<String, Object?> inputs;
  final Map<String, EngineeringValue> metrics;
  final List<String> assumptions, warnings;
  Map<String, Object?> toJson() => {
    'key': key, 'title': title, 'status': status, 'inputs': inputs,
    'metrics': metrics.map((k, v) => MapEntry(k, v.toJson())),
    'formula': formula, 'assumptions': assumptions, 'warnings': warnings,
    'calculatedAt': DateTime.now().toUtc().toIso8601String(), 'engineVersion': '1.1.0',
  };
}

/// Engineering screening calculations. These results are never a substitute
/// for complete standards-based design, manufacturer data or professional sign-off.
class AdvancedEngineering {
  static const transformerRatingsKva = <double>[10,16,25,40,63,100,160,200,250,315,400,500,630,800,1000,1250,1600,2000,2500,3150,4000,5000,6300,8000,10000];

  static void positive(double x, String name) { if (!x.isFinite || x <= 0) throw ArgumentError('$name must be finite and greater than zero.'); }
  static void range(double x, String name, double min, double max) { if (!x.isFinite || x < min || x > max) throw ArgumentError('$name must be between $min and $max.'); }

  static AdvancedEngineeringResult solarMonthlyYield({required double dcKwp, required List<double> monthlyPoaKwhM2Day, required double performanceRatioPercent, required double additionalLossPercent, double degradationPercent = .5, int operatingYear = 1}) {
    positive(dcKwp, 'DC capacity');
    if (monthlyPoaKwhM2Day.length != 12) throw ArgumentError('Enter exactly 12 monthly POA irradiation values.');
    for (final v in monthlyPoaKwhM2Day) { range(v, 'Monthly POA irradiation', 0, 12); }
    range(performanceRatioPercent, 'Performance ratio', 1, 100); range(additionalLossPercent, 'Additional losses', 0, 80); range(degradationPercent, 'Degradation', 0, 5);
    if (operatingYear < 1 || operatingYear > 40) throw ArgumentError('Operating year must be 1–40.');
    const days = [31,28,31,30,31,30,31,31,30,31,30,31];
    final factor = performanceRatioPercent/100 * (1-additionalLossPercent/100) * math.pow(1-degradationPercent/100, operatingYear-1).toDouble();
    final monthly = List<double>.generate(12, (i) => dcKwp * monthlyPoaKwhM2Day[i] * days[i] * factor);
    final annual = monthly.fold<double>(0, (a,b) => a+b);
    return AdvancedEngineeringResult(key:'solar_resource', title:'Monthly solar energy estimate', status:'RESOURCE-BASED ESTIMATE', inputs:{'dcKwp':dcKwp,'monthlyPoaKwhM2Day':monthlyPoaKwhM2Day,'performanceRatioPercent':performanceRatioPercent,'additionalLossPercent':additionalLossPercent,'degradationPercent':degradationPercent,'operatingYear':operatingYear}, metrics:{
      'Annual energy':EngineeringValue(annual,'kWh/year',digits:0),'Average monthly energy':EngineeringValue(annual/12,'kWh/month',digits:0),'Specific yield':EngineeringValue(annual/dcKwp,'kWh/kWp/year',digits:0),'CUF':EngineeringValue(annual/(dcKwp*8760)*100,'%'),
      for(var i=0;i<12;i++) 'Month ${i+1}':EngineeringValue(monthly[i],'kWh',digits:0),
    }, formula:'E(month) = DC kWp × POA irradiation × days × PR × (1 − losses) × degradation factor.', assumptions:const ['POA irradiation must have a named source, plane definition and report date.','February is treated as 28 days.','This is not a bankable simulation or a generation guarantee.'], warnings:const ['Detailed temperature, clipping, availability, curtailment and time-series shade mismatch are not modelled.']);
  }

  static AdvancedEngineeringResult inverterDcAc({required double dcKwp, required double acKw, required double minimumRatio, required double maximumRatio}) {
    positive(dcKwp,'DC capacity'); positive(acKw,'Inverter AC rating'); positive(minimumRatio,'Minimum ratio'); positive(maximumRatio,'Maximum ratio');
    if(minimumRatio>maximumRatio) throw ArgumentError('Minimum ratio must not exceed maximum ratio.');
    final ratio=dcKwp/acKw; final warnings=<String>[]; if(ratio<minimumRatio||ratio>maximumRatio) warnings.add('DC/AC ratio is outside the project-selected range; confirm clipping, MPPT envelope and warranty limits.');
    return AdvancedEngineeringResult(key:'inverter_sizing',title:'Inverter DC/AC allocation',status:warnings.isEmpty?'WITHIN ENTERED RATIO RANGE':'REVIEW REQUIRED',inputs:{'dcKwp':dcKwp,'acKw':acKw,'minimumRatio':minimumRatio,'maximumRatio':maximumRatio},metrics:{'DC/AC ratio':EngineeringValue(ratio,'x'),'DC capacity':EngineeringValue(dcKwp,'kWp'),'AC rating':EngineeringValue(acKw,'kW'),'AC/DC percentage':EngineeringValue(acKw/dcKwp*100,'%')},formula:'DC/AC ratio = installed PV DC capacity ÷ inverter AC rating.',assumptions:const ['Select acceptable ratios from project design basis and manufacturer documentation.'],warnings:warnings);
  }

  static AdvancedEngineeringResult acCableDrop({required double currentA,required double lengthM,required double voltageV,required double powerFactor,required double resistanceOhmPerKm,required double reactanceOhmPerKm,required bool threePhase,double projectLimitPercent=3}) {
    positive(currentA,'Current'); positive(lengthM,'One-way length'); positive(voltageV,'Voltage'); range(powerFactor,'Power factor',.1,1); positive(resistanceOhmPerKm,'Resistance'); range(reactanceOhmPerKm,'Reactance',0,100); range(projectLimitPercent,'Drop criterion',.1,20);
    final sinPhi=math.sqrt(math.max(0,1-powerFactor*powerFactor)); final f=threePhase?math.sqrt(3):2.0; final drop=f*currentA*(lengthM/1000)*(resistanceOhmPerKm*powerFactor+reactanceOhmPerKm*sinPhi); final pct=drop/voltageV*100;
    final warnings=<String>[]; if(pct>projectLimitPercent) warnings.add('Voltage drop exceeds the project-entered criterion.');
    return AdvancedEngineeringResult(key:'ac_cable',title:'AC cable voltage-drop screening',status:warnings.isEmpty?'SCREENING WITHIN ENTERED LIMIT':'REVIEW CONDUCTOR',inputs:{'currentA':currentA,'lengthM':lengthM,'voltageV':voltageV,'powerFactor':powerFactor,'resistanceOhmPerKm':resistanceOhmPerKm,'reactanceOhmPerKm':reactanceOhmPerKm,'threePhase':threePhase,'projectLimitPercent':projectLimitPercent},metrics:{'Voltage drop':EngineeringValue(drop,'V'),'Voltage drop percent':EngineeringValue(pct,'%'),'Receiving voltage estimate':EngineeringValue(voltageV-drop,'V')},formula:threePhase?'ΔV = √3 × I × L(km) × (R cosφ + X sinφ)':'ΔV = 2 × I × L(km) × (R cosφ + X sinφ)',assumptions:const ['R and X are entered in ohm/km at design conductor temperature.','Balanced steady-state load approximation.'],warnings:[...warnings,'No ampacity, grouping derating, short-circuit withstand, harmonics, motor starting or protection coordination is checked.']);
  }

  static AdvancedEngineeringResult transformerSizing({required double maximumDemandKw,required double powerFactor,required double loadingLimitPercent,required double marginPercent}) {
    positive(maximumDemandKw,'Maximum demand'); range(powerFactor,'Power factor',.1,1); range(loadingLimitPercent,'Loading limit',10,100); range(marginPercent,'Design margin',0,100);
    final kva=maximumDemandKw/powerFactor; final required=kva*(1+marginPercent/100)/(loadingLimitPercent/100); final selected=transformerRatingsKva.firstWhere((v)=>v>=required,orElse:()=>transformerRatingsKva.last); final warnings=<String>[]; if(required>transformerRatingsKva.last) warnings.add('Required rating exceeds the built-in selection series; confirm available equipment with the manufacturer and utility.');
