    range(basicWindSpeedMps,'Basic wind speed',1,100); for(final e in <(double,String)>[(k1,'K1'),(k2,'K2'),(k3,'K3'),(k4,'K4')]){range(e.$1,e.$2,.1,3);} range(forceCoefficient,'Force coefficient',.1,5); positive(effectiveAreaM2,'Effective area');
    final vz=basicWindSpeedMps*k1*k2*k3*k4; final q=.6*vz*vz; final force=q*forceCoefficient*effectiveAreaM2/1000;
    return AdvancedEngineeringResult(key:'wind_basis',title:'Wind design-basis screening',status:'STRUCTURAL ENGINEER REVIEW REQUIRED',inputs:{'basicWindSpeedMps':basicWindSpeedMps,'k1':k1,'k2':k2,'k3':k3,'k4':k4,'forceCoefficient':forceCoefficient,'effectiveAreaM2':effectiveAreaM2},metrics:{'Design speed from entered factors':EngineeringValue(vz,'m/s'),'Reference velocity pressure':EngineeringValue(q,'N/m²'),'Reference pressure':EngineeringValue(q/1000,'kN/m²'),'Screening force':EngineeringValue(force,'kN')},formula:'Vd = Vb × K1 × K2 × K3 × K4; q = 0.6Vd²; F = q × Cf × A.',assumptions:const ['Factors must be independently selected from the applicable standard edition and project location/terrain/height basis.','This formula is only a reference velocity-pressure screen.'],warnings:const ['No code wind map/factor tables, roof zones, pressure coefficients, internal pressure, dynamic response, load combinations, members, anchors, connections or foundation design are completed. Not an IS 875 approval.']);
