    final l=spanM*1000,w=loadNPerM/1000,m=w*l*l/8,stress=m/sectionModulusMm3,defl=(5*w*math.pow(l,4)/(384*elasticModulusMpa*inertiaMm4)).toDouble(),limit=l/deflectionRatio; final warnings=<String>[];if(stress>allowableStressMpa)warnings.add('Bending stress exceeds entered allowable stress.');if(defl>limit)warnings.add('Deflection exceeds entered span/ratio limit.');
