    return AdvancedEngineeringResult(key:'foundation',title:'Isolated footing bearing screen',status:warnings.isEmpty?'BEARING SCREEN WITHIN INPUT LIMIT':'FOUNDATION REVIEW REQUIRED',inputs:{'verticalLoadKn':verticalLoadKn,'momentXKnM':momentXKnM,'momentYKnM':momentYKnM,'lengthM':lengthM,'widthM':widthM,'depthM':depthM,'safeBearingKpa':safeBearingKpa},metrics:{'Average pressure':EngineeringValue(avg,'kPa'),'Maximum pressure':EngineeringValue(qmax,'kPa'),'Minimum pressure':EngineeringValue(qmin,'kPa'),'Bearing utilisation':EngineeringValue(qmax/safeBearingKpa*100,'%'),'Concrete volume':EngineeringValue(area*depthM,'m³')},formula:'Rectangular rigid footing: qmax/min = P/A ± 6Mx/(B L²) ± 6My/(L B²); volume=L×B×D.',assumptions:const ['Linear soil-pressure distribution; moments and vertical load are at footing base.'],warnings:[...warnings,'No geotechnical investigation, settlement, sliding, overturning, punching/one-way shear, reinforcement, pedestal or anchor design.']);
