  static AdvancedEngineeringResult financial({required double annualGenerationKwh,required double tariffInrKwh,required double projectCostInr,required double omPercent,required double degradationPercent,required double tariffEscalationPercent,required double discountRatePercent,required int years}) {
    positive(annualGenerationKwh,'Annual generation');range(tariffInrKwh,'Tariff',0,1000);positive(projectCostInr,'Project cost');range(omPercent,'O&M',0,30);range(degradationPercent,'Degradation',0,5);range(tariffEscalationPercent,'Tariff escalation',0,20);range(discountRatePercent,'Discount rate',0,40);if(years<1||years>40)throw ArgumentError('Analysis period must be 1–40 years.');final gross=annualGenerationKwh*tariffInrKwh,om=projectCostInr*omPercent/100;var npv=-projectCostInr,cumulative=-projectCostInr,payback=double.nan,discountedEnergy=0.0,discountedCost=projectCostInr;
