    return AdvancedEngineeringResult(key:'financial',title:'Solar project financial screening',status:'INDICATIVE FINANCIAL MODEL',inputs:{'annualGenerationKwh':annualGenerationKwh,'tariffInrKwh':tariffInrKwh,'projectCostInr':projectCostInr,'omPercent':omPercent,'degradationPercent':degradationPercent,'tariffEscalationPercent':tariffEscalationPercent,'discountRatePercent':discountRatePercent,'years':years},metrics:{'First-year gross value':EngineeringValue(gross,'INR/year',digits:0),'First-year O&M':EngineeringValue(om,'INR/year',digits:0),'Simple payback':EngineeringValue(payback.isNaN?0:payback,payback.isNaN?'not reached':'years',digits:1),'NPV':EngineeringValue(npv,'INR',digits:0),'Discounted LCOE proxy':EngineeringValue(discountedCost/discountedEnergy,'INR/kWh')},formula:'Cash flow = degraded generation × escalated tariff − O&M; NPV discounts cash flow; LCOE proxy=discounted costs÷discounted energy.',assumptions:const ['O&M is constant as a percentage of initial capex.','No tax, debt, inverter replacement, residual value, subsidy, insurance or escalation of O&M.'],warnings:const ['Indicative comparison only; not a lender, tax or project-finance model.']);
