  static AdvancedEngineeringResult batteryCRate({required double nominalEnergyKwh,required double chargePowerKw,required double dischargePowerKw,required double dcVoltageV,required double maximumChargeC,required double maximumDischargeC}) {
    positive(nominalEnergyKwh,'Nominal battery energy'); range(chargePowerKw,'Charge power',0,1e6); range(dischargePowerKw,'Discharge power',0,1e6); positive(dcVoltageV,'DC voltage'); positive(maximumChargeC,'Maximum charge C-rate'); positive(maximumDischargeC,'Maximum discharge C-rate'); final chargeC=chargePowerKw/nominalEnergyKwh,dischargeC=dischargePowerKw/nominalEnergyKwh,chargeA=chargePowerKw*1000/dcVoltageV,dischargeA=dischargePowerKw*1000/dcVoltageV; final warnings=<String>[]; if(chargeC>maximumChargeC)warnings.add('Charge C-rate exceeds the entered battery limit.'); if(dischargeC>maximumDischargeC)warnings.add('Discharge C-rate exceeds the entered battery limit.');
    return AdvancedEngineeringResult(key:'battery_c_rate',title:'Battery power and C-rate screening',status:warnings.isEmpty?'WITHIN ENTERED C-RATE LIMITS':'BATTERY REVIEW REQUIRED',inputs:{'nominalEnergyKwh':nominalEnergyKwh,'chargePowerKw':chargePowerKw,'dischargePowerKw':dischargePowerKw,'dcVoltageV':dcVoltageV,'maximumChargeC':maximumChargeC,'maximumDischargeC':maximumDischargeC},metrics:{'Charge C-rate':EngineeringValue(chargeC,'C'),'Discharge C-rate':EngineeringValue(dischargeC,'C'),'Charge current estimate':EngineeringValue(chargeA,'A'),'Discharge current estimate':EngineeringValue(dischargeA,'A')},formula:'C-rate = power (kW) ÷ nominal energy (kWh); DC current = power × 1000 ÷ DC voltage.',assumptions:const ['Power is assumed constant at the entered nominal DC voltage.'],warnings:[...warnings,'No cell-level current sharing, voltage window, thermal control, BMS derating, ageing, fault current or manufacturer warranty checks.']);
  }

  static AdvancedEngineeringResult transformerFaultCurrent({required double transformerKva,required double secondaryVoltageV,required double impedancePercent}) {
    positive(transformerKva,'Transformer rating'); positive(secondaryVoltageV,'Secondary line voltage'); range(impedancePercent,'Transformer impedance',.1,30); final ratedCurrent=transformerKva*1000/(math.sqrt(3)*secondaryVoltageV),faultCurrent=ratedCurrent/(impedancePercent/100);
    return AdvancedEngineeringResult(key:'fault_current',title:'Transformer-fed three-phase fault-current estimate',status:'SOURCE-IMPEDANCE SCREEN ONLY',inputs:{'transformerKva':transformerKva,'secondaryVoltageV':secondaryVoltageV,'impedancePercent':impedancePercent},metrics:{'Transformer rated current':EngineeringValue(ratedCurrent,'A'),'Approximate terminal fault current':EngineeringValue(faultCurrent,'A'),'Fault level':EngineeringValue(math.sqrt(3)*secondaryVoltageV*faultCurrent/1000,'kVA')},formula:'Irated = kVA×1000/(√3×VLL); Isc ≈ Irated ÷ (Z%/100).',assumptions:const ['Infinite primary source and transformer impedance-only approximation at transformer terminals.'],warnings:const ['No upstream utility impedance, cable impedance, motor contribution, X/R ratio, asymmetry, peak making current or breaker interrupting/coordination check.']);
