  static AdvancedEngineeringResult rooftopLoadScreen({required int moduleCount,required double moduleMassKg,required double mountingMassPerModuleKg,required double effectiveAreaM2,required double enteredAllowableLoadKpa}) {
    if(moduleCount<1||moduleCount>1000000)throw ArgumentError('Module count must be 1–1,000,000.'); positive(moduleMassKg,'Module mass'); range(mountingMassPerModuleKg,'Mounting mass per module',0,1000); positive(effectiveAreaM2,'Effective distributed area'); positive(enteredAllowableLoadKpa,'Entered allowable roof load'); final totalMass=moduleCount*(moduleMassKg+mountingMassPerModuleKg),load=totalMass*9.80665/effectiveAreaM2/1000,util=load/enteredAllowableLoadKpa*100; final warnings=<String>[];if(load>enteredAllowableLoadKpa)warnings.add('Estimated average dead load exceeds the entered allowable roof load.');
