  static AdvancedEngineeringResult concreteAndRebarTakeoff({required double lengthM,required double widthM,required double depthM,required double concreteWastePercent,required double reinforcementKgPerM3}) {
    positive(lengthM,'Length');positive(widthM,'Width');positive(depthM,'Depth');range(concreteWastePercent,'Concrete waste',0,30);range(reinforcementKgPerM3,'Reinforcement rate',0,500);final net=lengthM*widthM*depthM,order=net*(1+concreteWastePercent/100),steel=net*reinforcementKgPerM3;
